#!/bin/bash
# 26_music_rank_polish.sh
# 排行榜精修 5 项：
# 1) 更新时间动态化（加载完成时间戳 -> "刚刚/x分钟前"）
# 2) 右上角榜单名胶囊化
# 3) 列表项紧凑化（64dp/46dp/小字号）
# 4) SQ 标签按真实音质（quality 非空）计算
# 5) 封面 Coil AsyncImage 加载真实 coverUrl
set -e
cd "$(dirname "$0")/../.." 2>/dev/null || true
BASE="avbox"
RANK_KT="$BASE/app/src/main/java/com/github/tvbox/osc/ui/music/rank/RankScreen.kt"

if [ -f "$RANK_KT" ] && grep -q "紧凑精致版：64dp 行高" "$RANK_KT" 2>/dev/null; then
  echo "跳过（RankScreen.kt 精修版已写入）"
else
  mkdir -p "$(dirname "$RANK_KT")"
  echo "" | base64 -d > "$RANK_KT"
  echo "已写入 rank/RankScreen.kt（精修版）"
fi

TARGET="$BASE/app/src/main/java/com/github/tvbox/osc/ui/activity/MusicHomeActivity.kt"
if [ ! -f "$TARGET" ]; then
  echo "FATAL: 未找到 $TARGET，精修接线无法应用，构建中止"
  exit 1
fi

python3 - "$TARGET" <<'PYEOF'
import re, sys

path = sys.argv[1]
src = open(path, encoding='utf-8').read()
MARK = '// NAV_WIRE_V2'
if MARK in src:
    print("已打过补丁，跳过"); sys.exit(0)

def func_span(src, sig):
    s = src.find(sig)
    assert s > 0, f"未找到 {sig}"
    m = re.search(r'\n(?:/\*\*[\s\S]*?\*/\n)?(?:@Composable\n)?(?:private )?fun \w+', src[s+20:])
    end = s + 20 + m.start() if m else len(src)
    return s, end

# ---- A+B: 限定在 RankingTab 内 ----
s, end = func_span(src, 'fun RankingTab(')
body = src[s:end]

# A: 加载完成时间戳状态
old_a = '    var isLoading by remember { mutableStateOf(true) }'
assert body.count(old_a) == 1, "A锚点不唯一"
body = body.replace(old_a, old_a + '\n    var chartLoadedAt by remember { mutableStateOf(0L) } // NAV_WIRE_V2: 榜单加载完成时间戳')

# B: finally 里打时间戳
old_b = '        } finally {\n            isLoading = false\n        }'
assert body.count(old_b) == 1, "B锚点不唯一"
body = body.replace(old_b, '        } finally {\n            isLoading = false\n            chartLoadedAt = System.currentTimeMillis() // NAV_WIRE_V2\n        }')
src = src[:s] + body + src[end:]

# ---- C: 更新时间文案（插在 RankScreen 调用前） ----
old_c = '    // NAV_WIRE_V1: 排行榜新版 UI（RankScreen）'
assert src.count(old_c) == 1, "C锚点不唯一"
new_c = '''    // NAV_WIRE_V2: 动态更新时间（源站无真实时间戳，用加载完成时间推算）
    val updateTimeText = remember(chartLoadedAt) {
        val diffMin = (System.currentTimeMillis() - chartLoadedAt) / 60000
        when {
            chartLoadedAt == 0L -> "刚刚"
            diffMin < 1 -> "刚刚"
            diffMin < 60 -> "$diffMin 分钟前"
            diffMin < 1440 -> "${diffMin / 60} 小时前"
            else -> java.text.SimpleDateFormat("MM-dd HH:mm", java.util.Locale.getDefault())
                .format(java.util.Date(chartLoadedAt))
        }
    }
''' + old_c
src = src.replace(old_c, new_c)

# ---- D1: hasSQ 按真实音质计算 ----
old_d1 = 'songs = songs.map { RankSong(title = it.title, artist = it.artist, coverUrl = it.picUrl) }'
assert src.count(old_d1) == 1, "D1锚点不唯一"
src = src.replace(old_d1,
    'songs = songs.map {\n            RankSong(\n                title = it.title,\n                artist = it.artist,\n                coverUrl = it.picUrl,\n                hasSQ = it.quality.isNotBlank(), // NAV_WIRE_V2: 真实音质（SQ/HQ/24bit）才显示\n            )\n        }')

# ---- D2: 传入动态更新时间 ----
old_d2 = '        title = platformName,\n'
assert src.count(old_d2) == 1, "D2锚点不唯一"
src = src.replace(old_d2, '        title = platformName,\n        updateTime = updateTimeText, // NAV_WIRE_V2\n')

open(path, 'w', encoding='utf-8').write(src)

# 校验
d = 0
for ch in src: d += 1 if ch == '{' else (-1 if ch == '}' else 0)
print("括号平衡:", d)
print("V2标记数:", src.count(MARK))
print("updateTimeText:", src.count('updateTime = updateTimeText'))
print("hasSQ真实:", src.count('hasSQ = it.quality.isNotBlank()'))
PYEOF
echo "精修接线完成"
